const expected = $("Load RAG Cases").all().map(i => i.json);
const actual = $input.all().map(i => i.json);

let correct = 0;
const rows = [];

for (let i = 0; i < expected.length; i++) {
  const e = expected[i];
  const a = actual[i] || {};
  const got = a.sop_found ? String(a.sop_source || "").slice(0, 7) : "NONE";
  const ok = got === e.expected_sop;
  if (ok) correct++;
  rows.push({ case_id: e.case_id, subject: e.subject, expected: e.expected_sop, got, score: a.sop_score, ok, suggested_fix: a.suggested_fix });
}

return [{ json: { total: expected.length, correct, accuracy_pct: Math.round((correct / expected.length) * 1000) / 10, rows } }];
